(function(root){
  'use strict';
  const M=typeof module!=='undefined'?require('./exploration-map.js'):root.ExplorationMap;
  // Trial scenes, not final story canon. Labels and sensory classes are internal.
  const EVENTS={
    surgery:{name:'작동하지 않는 수술대',biomes:['hospital'],scene:'비어 있는 수술대 옆에서 금속 쟁반이 저절로 흔들린다.',clue:'금속을 내려놓는 소리가 일정한 간격으로 반복된다.',choices:[{id:'recover',label:'쟁반의 부품 회수',time:2,gold:6,text:'시간을 들여 손이 닿는 부품만 회수한다.'},{id:'decode',label:'남은 기록 해독',time:3,reward:true,text:'카드 세 장 중 하나를 선택하거나 건너뛴다.'},{id:'activate',label:'수술대 가동',combat:true,text:'사냥꾼과 교전한다. 전투 진입 비용을 지불하며 패배할 수 있다.'},{id:'leave',label:'그대로 두기',time:0,text:'보상 없이 기록만 남긴다.'}]},
    cough:{name:'열두 번째 기침',biomes:['hospital'],scene:'빈 병실의 녹음기가 같은 기침을 열두 번 반복한다.',clue:'짧은 기침이 되풀이된다. 숨을 고르는 소리는 들리지 않는다.',choices:[{id:'observe',label:'녹음의 끝까지 듣기',time:2,heal:3,text:'생존 동료 HP 3 회복. 전투불능은 회복하지 않는다.'},{id:'dismantle',label:'녹음기 분해',time:2,gold:5,text:'시간을 들여 부품을 회수한다.'},{id:'leave',label:'문 닫고 나오기',time:0,text:'보상 없이 기록만 남긴다.'}]},
    vending:{name:'비어 있는 자판기',biomes:['city'],scene:'텅 빈 자판기 안에서 동전이 굴러다닌다.',clue:'동전이 떨어지는 소리가 들리지만 기계의 불빛은 꺼져 있다.',choices:[{id:'dismantle',label:'아래 덮개 열기',time:2,gold:7,text:'남은 동전을 회수한다.'},{id:'wait',label:'잠시 기대어 쉬기',time:1,heal:2,text:'생존 동료 HP 2 회복. 전투불능은 회복하지 않는다.'},{id:'leave',label:'지나가기',time:0,text:'보상 없이 기록만 남긴다.'}]},
    broadcast:{name:'거꾸로 울리는 안내 방송',biomes:['station'],scene:'다음 역을 알리는 목소리가 끝에서 처음으로 되감긴다.',clue:'안내 방송이 거꾸로 흘러나온다. 끝난 문장이 다시 시작된다.',choices:[{id:'record',label:'방송 기록 회수',time:2,reward:true,text:'카드 세 장 중 하나를 선택하거나 건너뛴다.'},{id:'follow',label:'닫힌 방송실 열기',combat:true,text:'추적자와 교전한다. 전투 진입 비용을 지불하며 패배할 수 있다.'},{id:'leave',label:'시간만 적어 두기',time:0,text:'보상 없이 기록만 남긴다.'}]},
    shadow:{name:'그림자가 하나 더 많은 문',biomes:['city','station'],scene:'문은 하나인데 바닥에는 문 두 개의 그림자가 드리운다.',clue:'문 아래의 그림자가 두 갈래로 갈라진다. 빛은 한 곳에서 온다.',choices:[{id:'trace',label:'두 번째 그림자 조사',time:3,reward:true,text:'카드 세 장 중 하나를 선택하거나 건너뛴다.'},{id:'mark',label:'안전한 쪽에 표식 남기기',time:1,text:'보상 없이 이 현상을 기록한다.'},{id:'leave',label:'거리를 두고 돌아서기',time:0,text:'보상 없이 기록만 남긴다.'}]}
  };
  const MODES=['sound','light','smell','temperature','vibration','air','space','time','biological','ritual'];
  const samples={
    threat:['안쪽에서 바닥을 긁는 소리가 들린다.','문틈의 불빛이 무언가에 가려졌다 돌아온다.','젖은 털 냄새가 바람을 타고 나온다.','문손잡이 부근에서 따뜻한 김이 올라온다.','무언가 무겁게 움직일 때마다 바닥이 울린다.','문 안쪽에서 거친 숨 같은 바람이 밀려온다.','문 아래로 움직이는 그림자가 지나간다.','불규칙한 발소리가 멈췄다가 이어진다.','문턱 안쪽에 젖은 발자국이 찍혀 있다.','문틈 너머에서 낯선 빛이 몸집처럼 흔들린다.'],
    resource:['가벼운 물건들이 서로 부딪치는 소리가 난다.','문 안쪽의 작은 물건에 빛이 반사된다.','오래된 종이와 금속 냄새가 섞여 나온다.','차가운 금속 냄새가 문틈에 머문다.','선반이 흔들리는 듯 작은 떨림이 전해진다.','먼지를 실은 바람이 낮게 흘러나온다.','문틈 아래로 반듯한 사물의 그림자가 보인다.','종이가 넘어가는 소리가 느린 간격으로 들린다.','누군가 만진 흔적이 먼지 사이에 남아 있다.','글자 같은 빛이 가까운 물체 위에 비친다.'],
    safe:['이쪽은 소리가 낮게 가라앉아 있다.','문 안쪽의 불빛이 일정하게 유지된다.','먼지 냄새 사이로 마른 천 냄새가 난다.','문 너머의 공기는 조금 서늘하다.','이 방향의 바닥은 조용하다.','느린 바람이 막힘 없이 지나간다.','문틀과 바닥의 선이 반듯하게 이어진다.','불빛이 깜빡이는 간격이 일정하다.','먼지가 오래 흐트러지지 않은 자국이 있다.','문 안쪽에서 희미한 빛이 잔잔히 번진다.']
  };
  Object.assign(samples,{anomaly:['문틀의 그림자가 빛보다 늦게 움직인다.','짧은 소리가 끝에서 처음으로 되돌아간다.','빛은 하나인데 그림자는 두 갈래로 나뉜다.'],unknown:['안쪽이 어두워 가까운 바닥만 보인다.','바람이 들어갔다 멈춘다. 그 너머는 조용하다.','빛이 문 앞에서 끊겨 안쪽은 확인되지 않는다.'],narrative:['묶인 종이 뭉치가 바람에 바스락거린다.','흐릿한 글자 모양의 빛이 문틈에 비친다.','마른 종이 냄새가 문 너머에서 새어 나온다.']});
  const SIGNS=Object.entries(samples).flatMap(([group,texts])=>texts.map((text,i)=>({id:group+'-'+MODES[i],semanticGroup:group,sensoryMode:MODES[i],text})));
  const props={hospital:{sound:'천장 배관',light:'형광등',space:'병실 문'},city:{sound:'거리의 배수관',light:'가로등',space:'상점 문'},station:{sound:'승강장 배관',light:'안내등',space:'대합실 문'}};
  function assignments(seed,map){const types=Object.keys(EVENTS).filter(id=>EVENTS[id].biomes.includes(map.biomeId));const nodes=map.nodes.filter(n=>n.kind==='room'&&!n.encounter).sort((a,b)=>M.hash(seed+':event:'+a.id)-M.hash(seed+':event:'+b.id)||a.id.localeCompare(b.id));return nodes.slice(0,2).map((n,i)=>({id:n.id+':event',node:n.id,type:types[i%types.length],status:'available',choice:null}));}
  function initialize(seed,map){if(map.roomEvents===undefined)map.roomEvents=assignments(seed,map);}
  function eventAt(map,nodeId){return map.roomEvents?.find(e=>e.node===nodeId);}
  function validate(seed,map){const expected=assignments(seed,map);if(!Array.isArray(map.roomEvents)||map.roomEvents.length!==expected.length)throw Error('사건 배정 오류');map.roomEvents.forEach((e,i)=>{const d=expected[i];if(e.id!==d.id||e.node!==d.node||e.type!==d.type||!['available','combat','resolved','failed'].includes(e.status)||e.choice!==null&&!EVENTS[e.type].choices.some(c=>c.id===e.choice)||e.status==='available'&&e.choice!==null||e.status!=='available'&&e.choice===null)throw Error('사건 저장 오류');});}
  function roomName(map,n){if(n.kind==='entry')return '진입 지점';if(n.kind==='exit')return '발견한 연결구';const event=eventAt(map,n.id);if(event)return EVENTS[event.type].name;if(n.interactions.some(i=>i.kind==='record'))return map.biomeId==='hospital'?'기록실':map.biomeId==='city'?'문서 보관소':'역무실';if(n.interactions.some(i=>i.kind==='shelter'))return '쉴 수 있는 방';if(n.interactions.some(i=>i.kind==='workbench'))return '작업대가 있는 방';return map.biomeId==='hospital'?'병원 복도':map.biomeId==='city'?'빈 골목':'대합실 통로';}
  function signs(run){const from=run.map.nodes.find(n=>n.id===run.nodeId);return Object.entries(from.exits).map(([direction,id])=>{const n=run.map.nodes.find(n=>n.id===id),e=eventAt(run.map,id);if(n.visited){const state=e?e.status==='resolved'?'사건 기록 완료':'선택을 남겨 둔 장소':n.encounter?n.encounter.cleared?'위협을 넘어선 장소':'위협을 확인한 장소':n.interactions.length&&n.interactions.every(i=>i.resolved)?'조사를 마친 장소':'이미 방문한 장소';return {direction,text:roomName(run.map,n)+'로 이어진다. '+state+'다.',known:true};}if(e)return {direction,text:EVENTS[e.type].clue,known:false};const group=n.encounter&&!n.encounter.cleared?'threat':n.interactions.some(i=>!i.resolved&&i.kind==='record')?'narrative':n.interactions.some(i=>!i.resolved&&i.kind==='cache')?'resource':n.interactions.some(i=>!i.resolved)?'safe':'unknown',pool=SIGNS.filter(s=>s.semanticGroup===group),sample=pool[M.hash(run.seed+':'+run.depth+':'+from.id+':'+direction+':'+group)%pool.length],p=props[run.map.biomeId];return {direction,text:sample.text+(p[sample.sensoryMode]?' '+p[sample.sensoryMode]+' 너머에서 느껴진다.':''),known:false};});}
  const api={EVENTS,MODES,SIGNS,assignments,initialize,eventAt,validate,roomName,signs};if(typeof module!=='undefined')module.exports=api;root.ExplorationContent=api;
})(typeof globalThis!=='undefined'?globalThis:this);
